/** Keep nearby card contents mounted; retain measured grid spans as scroll placeholders. */
export function createCardWindow(container,{margin=1000,onMount=()=>{}}={}){
 const records=new Map();
 const observer=new IntersectionObserver(entries=>{for(const entry of entries){const card=entry.target,record=records.get(card);if(!record)continue;if(entry.isIntersecting){if(record.html!==null){record.body.innerHTML=record.html;record.html=null;card.dataset.virtual='mounted';onMount(card)}}else if(record.html===null&&card.dataset.measured&&!card.contains(document.activeElement)){record.html=record.body.innerHTML;record.body.replaceChildren();card.dataset.virtual='placeholder'}}},{rootMargin:margin+'px 0px'});
 return {observe(card){const body=card.querySelector('.card-body');records.set(card,{body,html:null});card.dataset.virtual='mounted';observer.observe(card)},remove(card){observer.unobserve(card);records.delete(card)},reset(){observer.disconnect();records.clear()},refreshSaved(saved){for(const [card,record] of records){if(record.html!==null)continue;const button=card.querySelector('[data-save]');if(button)button.setAttribute('aria-pressed',String(saved.has(button.dataset.save)))}},get size(){return records.size}};
}
